def iroot(x, k):
    lo, hi = 0, 1
    while hi ** k <= x:
        hi *= 2
    while lo < hi:
        mid = (lo + hi) // 2
        if mid ** k < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
